fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let target = width as usize;
    let orig_len = orig.len();

    if orig_len >= target {
        // If the original is already as long or longer, return it unchanged.
        orig
    } else {
        // Otherwise, build a new vector with leading fillchars.
        let mut res = Vec::with_capacity(target);
        res.extend(std::iter::repeat(fillchar).take(target - orig_len));
        res.extend(orig);
        res
    }
}

